import {unique,display,pipeChoice,filterRows,drillLabel} from './lib/reference.js';
const configs={
 threads:{data:'unified',title:'Unified tap drills.',subtitle:'Drill selections for UNC, UNF and UNEF cutting taps.',group:'02 / THREADS & TAP DRILLS',family:'threads'},
 'metric-taps':{data:'metric-taps',title:'Metric tap drills.',subtitle:'Coarse and fine threads, drill sizes and minor-diameter limits.',group:'02 / THREADS & TAP DRILLS',family:'threads'},
 'pipe-taps':{data:'pipe-taps',title:'Pipe tap drills.',subtitle:'Hole sizes for NPT and NPSC pipe taps.',group:'02 / THREADS & TAP DRILLS',family:'threads'},
 counterbores:{data:'counterbores-inch',title:'Inch counterbores.',subtitle:'Clearance and head recess dimensions for socket head cap screws.',group:'03 / COUNTERBORES',family:'counterbores'},
 'metric-counterbores':{data:'counterbores-metric',title:'Metric counterbores.',subtitle:'Clearance and head recess dimensions for metric socket head cap screws.',group:'03 / COUNTERBORES',family:'counterbores'},
 strength:{data:'inch-strength',title:'Inch bolt grades.',subtitle:'Strength values, diameter ranges and head identification.',group:'04 / BOLT & MATERIAL STRENGTH',family:'strength'},
 'metric-strength':{data:'metric-strength',title:'Metric bolt strength.',subtitle:'Thread area, strength, proof loads and hardness by property class.',group:'04 / BOLT & MATERIAL STRENGTH',family:'strength'},
 'stainless-strength':{data:'stainless-strength',title:'Stainless bolt strength.',subtitle:'Metric stainless steel grades and strength classes.',group:'04 / BOLT & MATERIAL STRENGTH',family:'strength'},
 gears:{data:'gears',title:'Gear families.',subtitle:'Compare shaft arrangements, motion and operating characteristics.',group:'05 / GEARS',family:'gears'}
};
const tabs={threads:[['threads','Unified inch'],['metric-taps','Metric'],['pipe-taps','NPT / NPSC']],counterbores:[['counterbores','Inch'],['metric-counterbores','Metric']],strength:[['strength','Inch grades'],['metric-strength','Metric steel'],['stainless-strength','Stainless']]};
const cache=new Map(); let generation=0;
const e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const $=id=>document.getElementById(id);
function options(id,values,chosen){$(id).replaceChildren(...values.map(v=>{const o=document.createElement('option');o.value=v;o.textContent=v;return o;}));if(values.includes(chosen))$(id).value=chosen;}
const field=(id,label)=>`<label for="${id}">${label}</label><select id="${id}"></select>`;
const metrics=values=>values.map(([label,value,unit])=>`<div><dt>${e(label)}</dt><dd>${e(display(value,unit))}</dd></div>`).join('');
function table(headers,rows){return `<div class="table-wrap" role="region" aria-label="Reference chart" tabindex="0"><table><thead><tr>${headers.map(h=>`<th scope="col">${e(h)}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(r=>`<tr>${r.map(v=>`<td>${e(display(v))}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${headers.length}">No matching entries.</td></tr>`}</tbody></table></div>`;}
function counterDiagram(){return `<svg viewBox="0 0 500 210" role="img" aria-label="Counterbore section showing a wider recess above a smaller through clearance hole"><path d="M35 45H130V100H185V175H35ZM465 45H370V100H315V175H465Z" fill="#dce5ee" stroke="#203145" stroke-width="2"/><path d="M130 20H370M130 14V30M370 14V30M185 192H315M185 184V200M315 184V200" fill="none" stroke="#a75800" stroke-width="2"/><text x="250" y="15" text-anchor="middle" font-size="14">Counterbore diameter</text><text x="250" y="208" text-anchor="middle" font-size="14">Clearance diameter</text><path d="M250 30V182" stroke="#8294a7" stroke-dasharray="5 5"/></svg>`;}
const markNames={none:'No grade marking',radial3:'Three radial lines',radial5:'Five radial lines',radial6:'Six radial lines',cluster3:'Three adjacent radial lines',cluster6:'Six clustered radial lines','A325-1':'A325','A325-2':'A325 with three radial lines','A325-3':'Underlined A325','A490-1':'A490','A490-3':'Underlined A490',BC:'BC','307A':'307A'};
function markSvg(mark){const angles=mark==='radial3'?[0,120,240]:mark==='radial5'?[0,72,144,216,288]:mark==='radial6'?[0,60,120,180,240,300]:mark==='cluster3'||mark==='A325-2'?[-60,0,60]:mark==='cluster6'?[-75,-45,-15,15,45,75]:[];const lines=angles.map(a=>{const r=a*Math.PI/180;return `<path d="M${100+45*Math.sin(r)} ${100-45*Math.cos(r)}L${100+66*Math.sin(r)} ${100-66*Math.cos(r)}"/>`;}).join('');const text=mark.startsWith('A325')?'A325':mark.startsWith('A490')?'A490':['BC','307A'].includes(mark)?mark:'';return `<svg class="head-mark" viewBox="0 0 200 200" role="img" aria-label="${e(markNames[mark])}"><polygon points="100,18 171,59 171,141 100,182 29,141 29,59" fill="#eff3f7" stroke="#203145" stroke-width="3"/><g stroke="#203145" stroke-width="5">${lines}</g><text x="100" y="108" text-anchor="middle" fill="#203145" font-size="25">${text}</text>${mark.endsWith('-3')?'<path d="M65 118H135" stroke="#203145" stroke-width="3"/>':''}</svg>`;}
function gearIllustration(index,name){
 const x=[0,342,684][index%3],y=[0,356,696,1064][Math.floor(index/3)];
 return `<svg class="gear-illustration" viewBox="0 0 340 310" role="img" aria-label="Illustration of ${e(name)} showing its teeth and mating parts"><image href="./assets/gear-families.png" x="${-x}" y="${-y}" width="1024" height="1536"/></svg>`;
}
async function render(){
 const route=location.hash.slice(1),cfg=configs[route];if(!cfg)return;const token=++generation;const host=$('planned-page');host.hidden=false;
 host.innerHTML=`<p role="status">Loading local reference…</p>`;
 try{if(!cache.has(cfg.data)){const r=await fetch(`./data/${cfg.data}.json`);if(!r.ok)throw Error();cache.set(cfg.data,await r.json());}if(token!==generation||location.hash.slice(1)!==route)return;
 const data=cache.get(cfg.data),rows=data.rows;
 host.innerHTML=`${tabs[cfg.family]?`<nav class="key-tools" aria-label="${e(cfg.family)} tools">${tabs[cfg.family].map(([key,label])=>`<a href="#${key}" ${key===route?'aria-current="page"':''}>${label}</a>`).join('')}</nav>`:''}<div class="page-heading"><div><p class="eyebrow">${cfg.group}</p><h1>${cfg.title}</h1><p>${cfg.subtitle}</p></div></div><div id="tool-body"></div><section class="notes"><h2>Reference & scope</h2><div id="tool-notes"></div><p>Factual data from <a href="${e(data.source)}" target="_blank" rel="noreferrer">the AmesWeb reference</a>, retrieved September 13, 2026. Original layout, explanations and diagrams. A dash means unavailable or outside the stated scope.</p></section>`;
 document.title=`${cfg.title.replace(/\.$/,'')} · Shop Reference`;
 if(route==='gears'){
 $('tool-body').innerHTML=`<div class="gear-grid">${rows.map((r,i)=>`<article class="gear-card"><p class="eyebrow">${e(r.axes)} AXES</p><h2>${e(r.name)}</h2>${gearIllustration(i,r.name)}<p class="gear-look"><strong>Look for:</strong> ${e(r.teeth)}</p><dl><div><dt>Motion</dt><dd>${e(r.motion)}</dd></div><div><dt>Typical use</dt><dd>${e(r.use)}</dd></div><div><dt>Tradeoff</dt><dd>${e(r.tradeoff)}</dd></div><div><dt>Thrust</dt><dd>${e(r.thrust)}</dd></div></dl><p class="hint">${e(r.direction)}</p></article>`).join('')}</div>`;
 $('tool-notes').innerHTML='<p>Illustrations show recognizable gear families, not manufacturing geometry. These comparisons are not load ratings or a sizing method. Tooth geometry, lubrication, alignment, bearings and operating speed determine suitability. Worm self-locking requires a separate assessment.</p>';return;}
 let fields='';
 if(route==='threads'||route==='metric-taps')fields=field('pick-series','Thread series')+field('pick-size','Thread size');
 else if(route==='pipe-taps')fields=field('pick-size','Nominal pipe size')+field('pick-type','Thread type')+`<div id="reamer-field">${field('pick-reamer','Ream before tapping?')}</div>`;
 else if(cfg.family==='counterbores')fields=field('pick-size','Screw size')+field('pick-fit','Hole fit');
 else if(route==='strength')fields=field('pick-grade','Bolt grade')+field('pick-range','Diameter range · in');
 else if(route==='metric-strength')fields=field('pick-size','Metric thread')+field('pick-grade','Property class');
 else fields=field('pick-grade','Steel grade')+field('pick-class','Strength class');
 $('tool-body').innerHTML=`<div class="workspace"><form class="inputs" id="reference-form"><h2>${cfg.family==='strength'?'Fastener selection':'Size & options'}</h2>${fields}<p class="hint preference" id="input-note"></p></form><div class="result" aria-live="polite" aria-atomic="true"><p class="eyebrow" id="result-label"></p><h2 id="reference-main"></h2><p id="reference-sub" class="band"></p><dl id="reference-values" class="reference-values"></dl><p id="reference-note" class="result-note"></p></div></div><div id="tool-diagram"></div><section class="chart"><div class="section-heading"><h2>Reference chart</h2><label class="chart-filter" for="chart-query">Filter chart<input id="chart-query" type="search" placeholder="Find a size or grade"></label></div><div id="reference-chart"></div></section>`;
 $('reference-form').addEventListener('submit',event=>event.preventDefault());
 let chartHeaders=[],chartRows=[];
 if(route==='threads'||route==='metric-taps'){
 options('pick-series',unique(rows.map(r=>r.series)),route==='threads'?'UNC':'Coarse');
 const setSizes=()=>options('pick-size',rows.filter(r=>r.series===$('pick-series').value).map(r=>r.thread),route==='threads'?'1/4-20':'M6x1');setSizes();$('pick-series').addEventListener('change',()=>{setSizes();update();});
 $('input-note').textContent='For cutting taps. Forming taps require different hole sizes.';
 $('tool-notes').innerHTML=route==='threads'?'<p>Recommendations are discrete drill selections. Actual drilled diameter depends on tooling and material. UNC, UNF and UNEF are 60° Unified inch thread series.</p>':'<p>Dimensions are millimetres. Drill ≈ major diameter − pitch is an estimate, not a substitute for the tabulated drill. Nonpreferred sizes are identified in the results. Limits are for the displayed internal thread classes; no tolerance data is inferred for missing cells.</p>';
 } else if(route==='pipe-taps'){
 options('pick-size',rows.map(r=>r.size),'1/2');options('pick-type',['NPT','NPSC'],'NPT');options('pick-reamer',['yes','no'],'no');
 $('input-note').textContent='Nominal pipe size is not the pipe outside diameter.';$('tool-notes').innerHTML='<p>For NPT with a reamer, the source specifies ¾ inch taper per foot (diametral ratio 1:16). NPSC is straight pipe thread; the reamer choice does not apply. Decimal drill equivalents below retain the source rounding.</p>';
 } else if(cfg.family==='counterbores'){
 options('pick-size',unique(rows.map(r=>r.size)),route==='counterbores'?'1/4':'M6');options('pick-fit',['Normal','Close'],'Normal');$('input-note').textContent='Normal fit allows more assembly clearance. Close fit needs tighter hole alignment.';$('tool-diagram').innerHTML=`<div class="engineering-diagram">${counterDiagram()}<p class="hint">Section schematic. Maximum screw head height is not a finished counterbore depth specification.</p></div>`;
 $('tool-notes').innerHTML='<p>Use the recess diameter for the screw head and the clearance diameter for the shank. Edge relief must clear the screw’s under-head fillet or transition without removing more material than necessary. Check the drawing’s seating depth, tolerances and remaining wall thickness.</p>';
 } else if(route==='strength'){
 options('pick-grade',unique(rows.map(r=>r.grade)),'SAE Grade 5');const setRanges=()=>options('pick-range',rows.filter(r=>r.grade===$('pick-grade').value).map(r=>r.range));setRanges();$('pick-grade').addEventListener('change',()=>{setRanges();update();});$('input-note').textContent='Strengths are in ksi: 1 ksi = 1,000 psi.';
 $('tool-notes').innerHTML='<p>This edition preserves historical SAE/ASTM reference ranges and identifies corrections. A325/A490 data is historical; check the current F3125 specification when ordering. Head markings are schematic and omit manufacturer identification. An unmarked head alone cannot establish a bolt’s grade.</p><p>Common grades cross-checked with <a href="https://boltdepot.com/fastener-information/Materials-and-Grades/Bolt-Grade-Chart" target="_blank" rel="noreferrer">Bolt Depot</a>; A354 material checked with <a href="https://www.portlandbolt.com/technical/strength-requirements-by-grade/" target="_blank" rel="noreferrer">Portland Bolt</a>.</p>';
 } else if(route==='metric-strength'){
 options('pick-size',unique(rows.map(r=>r.thread)),'M6 x 1');options('pick-grade',unique(rows.map(r=>r.grade)),'8.8');$('input-note').textContent='Property class 9.8 applies only through M16.';
 $('tool-notes').innerHTML='<p>Reference editions: ISO 898-1:2013 and ISO 898-7:1992. Breaking torque is a test property, not an installation torque. Its listed values apply only within the source’s small/short-fastener test scope and tolerances 6g, 6f or 6e. Blank 0.2% proof-stress cells are not replaced with a different yield definition.</p><p>Nominal stress area As = (π/4)[(d₂+d₃)/2]². Tensile load = As × tensile stress; proof load = As × proof stress. Values use source table rounding (MPa × mm² = N). Hardness: Vickers test force ≥98 N; Brinell F = 30D².</p>';
 } else {
 options('pick-grade',unique(rows.map(r=>r.grade)),'A1,A2,A3,A4,A5');const setClasses=()=>options('pick-class',rows.filter(r=>r.grade===$('pick-grade').value).map(r=>r.property),'70');setClasses();$('pick-grade').addEventListener('change',()=>{setClasses();update();});$('input-note').textContent='Only valid grade / strength-class combinations are offered.';
 $('tool-notes').innerHTML='<p>ISO 3506-1:2009 reference scope: nominal thread diameter ≤39 mm, tested at 10–35°C. Austenitic, martensitic and ferritic groups have different properties. Strength class does not specify corrosion suitability for a particular environment.</p>';
 }
 function update(){let main='',sub='',label='',values=[],note='';
 if(route==='threads'||route==='metric-taps'){
 const r=rows.find(r=>r.thread===$('pick-size').value&&r.series===$('pick-series').value),metric=route==='metric-taps';label=metric?'TAP DRILL / MILLIMETRES':'TAP DRILL / INCHES';main=r.drill===null?'Not tabulated':metric?`${r.drill} mm`:drillLabel(r.drill,r.diameter);sub=`${r.thread} · ${r.series}`;note=r.note||'Use the tabulated recommendation with the tap maker’s material and hole-size guidance.';
 values=metric?[['Major diameter',r.major,'mm'],['Pitch',r.pitch,'mm'],['5H minor max',r.max5,'mm'],['6H minor max',r.max6,'mm'],['7H minor max',r.max7,'mm'],['Minor diameter min',r.min,'mm'],['d − P estimate',Number((r.major-r.pitch).toFixed(4)),'mm'],['Preferred series',r.nonpreferred?'Nonpreferred':'Standard listing']]:[['Decimal drill',r.diameter,'in'],['Major diameter',r.major,'in'],['Series',r.series]];
 chartHeaders=metric?['Thread','Series','Drill mm','5H max','6H max','7H max','Minor min']:['Thread','Series','Drill','Decimal in','Major in'];chartRows=filterRows(rows,$('chart-query').value).map(r=>metric?[r.thread,r.series,r.drill,r.max5,r.max6,r.max7,r.min]:[r.thread,r.series,drillLabel(r.drill,r.diameter),r.diameter,r.major]);
 }else if(route==='pipe-taps'){
 const r=rows.find(r=>r.size===$('pick-size').value),type=$('pick-type').value,p=pipeChoice(r,type,$('pick-reamer').value);$('reamer-field').hidden=type==='NPSC';label='PIPE TAP DRILL / INCHES';main=p.drill;sub=`${r.size} ${type}`;values=[['Decimal drill',p.diameter,'in'],['Pipe outside diameter',r.od,'in'],['Preparation',type==='NPSC'?'Straight thread':$('pick-reamer').value==='yes'?'Taper ream before tapping':'No reamer']];note='Drill selection may need adjustment for material and the required thread height.';
 chartHeaders=['Pipe size','OD in','NPT reamed','Decimal','NPT unreamed','Decimal','NPSC','Decimal'];chartRows=filterRows(rows,$('chart-query').value).map(r=>[r.size,r.od,r.nptReamerBit,r.nptReamerDec,r.nptNoReamerBit,r.nptNoReamerDec,r.npscBit,r.npscDec]);
 }else if(cfg.family==='counterbores'){
 const r=rows.find(r=>r.size===$('pick-size').value&&r.fit===$('pick-fit').value),u=data.unit;label=`COUNTERBORE DIAMETER / ${u==='in'?'INCHES':'MILLIMETRES'}`;main=`${r.counterbore} ${u}`;sub=`${r.size} screw · ${r.fit} fit`;values=[['Clearance drill',u==='in'?drillLabel(r.drill,r.clearance):r.drill,u==='mm'?'mm':''],['Clearance diameter',r.clearance,u],['Body diameter max',r.body,u],['Head height max',r.head,u],['Edge relief diameter',r.relief,u],[u==='in'?'Fillet max':'Transition diameter max',u==='in'?r.fillet:r.transition,u]];note='Head height is a screw dimension. Select machining depth from the drawing and required head clearance.';
 chartHeaders=['Screw','Fit',`Clearance ${u}`,`Counterbore ${u}`,`Relief ${u}`,`Head max ${u}`];chartRows=filterRows(rows,$('chart-query').value).map(r=>[r.size,r.fit,r.clearance,r.counterbore,r.relief,r.head]);
 }else if(route==='strength'){
 const r=rows.find(r=>r.grade===$('pick-grade').value&&r.range===$('pick-range').value);label='MINIMUM TENSILE STRENGTH';main=`${r.tensile} ksi`;sub=r.grade;values=[['Diameter range',r.range,'in'],['Proof stress',r.proof,'ksi'],['Yield strength',r.yield,'ksi'],['Material',r.material]];note=r.note||'These stresses are material/fastener properties, not allowable joint loads.';$('tool-diagram').innerHTML=`<div class="mark-panel">${markSvg(r.mark)}<div><h2>Head identification</h2><p>${e(markNames[r.mark])}</p><p class="hint">Schematic; manufacturer identification omitted.</p></div></div>`;chartHeaders=['Grade','Range in','Proof ksi','Tensile ksi','Yield ksi','Marking'];chartRows=filterRows(rows,$('chart-query').value).map(r=>[r.grade,r.range,r.proof,r.tensile,r.yield,markNames[r.mark]]);
 }else if(route==='metric-strength'){
 const r=rows.find(r=>r.thread===$('pick-size').value&&r.grade===$('pick-grade').value);label='MINIMUM TENSILE STRENGTH';main=r.tensile===null?'Outside scope':`${r.tensile} MPa`;sub=`${r.thread} · class ${r.grade}`;values=[['Stress area',r.area,'mm²'],['Ultimate tensile load',r.ultimate,'N'],['0.2% nonproportional stress',r.yield,'MPa'],['Proof stress',r.proof,'MPa'],['Proof load',r.proofLoad,'N'],['Breaking torque (test)',r.torque,'N·m'],['Vickers min / max',r.hvMin===null?null:`${r.hvMin} / ${r.hvMax}`,'HV'],['Brinell min / max',r.hbMin===null?null:`${r.hbMin} / ${r.hbMax}`,'HBW']];note=r.note||'Breaking torque is not tightening torque. Loads are fastener test properties, not allowable assembly loads.';chartHeaders=['Thread','Class','As mm²','Tensile MPa','Proof MPa','Proof load N'];chartRows=filterRows(rows,$('chart-query').value).map(r=>[r.thread,r.grade,r.area,r.tensile,r.proof,r.proofLoad]);
 }else{
 const r=rows.find(r=>r.grade===$('pick-grade').value&&r.property===$('pick-class').value);label='MINIMUM TENSILE STRENGTH';main=`${r.tensile} MPa`;sub=`${r.grade} · class ${r.property}`;values=[['Steel group',r.group],['0.2% nonproportional stress',r.yield,'MPa'],['Strength class',r.property]];note='Grade identifies the steel family; class identifies the mechanical-strength level.';chartHeaders=['Grade','Class','Group','Tensile MPa','0.2% stress MPa'];chartRows=filterRows(rows,$('chart-query').value).map(r=>[r.grade,r.property,r.group,r.tensile,r.yield]);
 }
 $('result-label').textContent=label;$('reference-main').textContent=main;$('reference-sub').textContent=sub;$('reference-values').innerHTML=metrics(values);$('reference-note').textContent=note;$('reference-chart').innerHTML=table(chartHeaders,chartRows);
 }
 host.querySelectorAll('select').forEach(s=>s.addEventListener('change',update));$('chart-query').addEventListener('input',update);update();
 }catch{if(token===generation&&location.hash.slice(1)===route)host.innerHTML='<h1>Reference unavailable</h1><p>The local dataset could not be loaded. Refresh to try again.</p>';}
}
window.addEventListener('hashchange',render);render();
